// Self-created RGB pixel patterns encoded and independently decoded with Pillow
// 10.2.0, JPEG quality=80/optimize=True; progressive only for that named fixture.
// No third-party images. Tests and installed-package checks need no Pillow.
export const JPEG_FIXTURES = {
  "tiny": {
    "width": 2,
    "height": 1,
    "base64": ""
  },
  "alternate": {
    "width": 2,
    "height": 1,
    "base64": ""
  },
  "small": {
    "width": 4,
    "height": 3,
    "base64": ""
  },
  "progressive": {
    "width": 4,
    "height": 3,
    "base64": ""
  },
  "screen": {
    "width": 240,
    "height": 320,
    "base64": ""
  }
}


export function jpegFixture(name = 'tiny') {
  const fixture = JPEG_FIXTURES[name]
  return { width: fixture.width, height: fixture.height,
    data: Uint8Array.from(atob(fixture.base64), character => character.charCodeAt(0)) }
}
